//go:embed app_gothic.js
var appJS []byte

func init() {
	gothic.RegisterModule("/_gothic/modules/app_gothic.js", appJS)
}

// RegisterProcedures mounts the declared procedures on s.
func RegisterProcedures(s *gothic.Server, impl Procedures) {
	s.RegisterProcedure("Increment", func(ctx context.Context, body []byte) (any, error) {
		return impl.Increment(ctx)
	})
}

// Increment is the client-side stub for the Increment procedure.
func Increment() (int, error) {
	panic("gothic: Increment is a client-only procedure")
}
